  }
  keys(e) {
    const n = this.items.length;
    if (!n) return;
    if (e.key === 'ArrowDown') this.cur = Math.min(n - 1, this.cur + 1);
    else if (e.key === 'ArrowUp') this.cur = Math.max(0, this.cur - 1);
    else if (e.key === 'Home') this.cur = 0;
    else if (e.key === 'End') this.cur = n - 1;
